function fact(n){if(n<0)return NaN;var r=1;for(var i=2;i<=n;i++)r*=i;return r;}
function perm(n,k){if(k<0||k>n)return 0;return fact(n)/fact(n-k);}
function comb(n,k){if(k<0||k>n)return 0;return fact(n)/(fact(k)*fact(n-k));}
function binomProb(n,k,p){if(p<0||p>1)return NaN;return comb(n,k)*Math.pow(p,k)*Math.pow(1-p,n-k);}
var EXPORTS={fact:fact,perm:perm,comb:comb,binomProb:binomProb};


